const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const wolfVolcano = ee.Geometry.Point([-91.35, 0.02]);
  const date1 = '2022-01-06';
  const date2 = '2022-01-07';

  // 2. Data Acquisition - VIIRS Daily Nighttime Lights
  const col1 = ee.ImageCollection('NOAA/VIIRS/001/VNP46A1')
    .filterBounds(wolfVolcano)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'));

  const col2 = ee.ImageCollection('NOAA/VIIRS/001/VNP46A1')
    .filterBounds(wolfVolcano)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'));

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Jan 6 Images: ${size1}, Jan 7 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('Missing data for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Get images and measure nighttime radiance
  const img1 = ee.Image(col1.first());
  const img2 = ee.Image(col2.first());

  // Use DNB_At_Sensor_Radiance_500m band
  const band = 'DNB_At_Sensor_Radiance_500m';

  // 4. Calculate pixel counts to detect C2
  const count1 = await img1.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wolfVolcano.buffer(5000),
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  const count2 = await img2.select(band).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: wolfVolcano.buffer(5000),
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  console.log(`Jan 6 Pixels: ${count1}, Jan 7 Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels for measurement.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean radiance values
  const val1 = await img1.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wolfVolcano.buffer(5000),
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  const val2 = await img2.select(band).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wolfVolcano.buffer(5000),
    scale: 500,
    maxPixels: 1e9
  }).get(band).getInfo();

  console.log(`Jan 6 Radiance: ${val1}, Jan 7 Radiance: ${val2}`);

  // 6. Validation & Final Answer
  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Brightness comparison: Jan7(${val2.toFixed(4)}) vs Jan6(${val1.toFixed(4)})`);

  if (val2 > val1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
